/* eslint-disable */

/**
 * Recursively decoded JSON from a `json` result cell. A JSON-internal integer
 * within JS's safe range comes back as a `number`; one outside it (but still
 * within i64) widens to `bigint`, so its exact value survives. The same rule
 * the networked `@zvndev/powdb-client` decoder uses. An integer beyond i64
 * range is the one lossy case (it falls back to a `number`); read the sibling
 * `pj1` bytes on the `json` WireValue for the exact, lossless form there.
 */
export type NativeJson =
  | null
  | boolean
  | number
  | bigint
  | string
  | NativeJson[]
  | { [key: string]: NativeJson }

/**
 * A single lossless typed result cell, mirroring the `@zvndev/powdb-client`
 * `WireValue` union so embedded and networked results present the same tagged
 * shape. `empty` (a missing / absent cell) is distinct from a JSON `null`.
 */
export type WireValue =
  | { type: "empty" }
  | { type: "int"; value: bigint }
  | { type: "float"; value: number }
  | { type: "bool"; value: boolean }
  | { type: "str"; value: string }
  | { type: "datetime"; value: bigint }
  | { type: "uuid"; value: Uint8Array }
  | { type: "bytes"; value: Buffer }
  | { type: "json"; value: NativeJson; pj1: Uint8Array }

/**
 * The result of a string-typed query (`query`, `querySql`, `queryReadonly`).
 *
 * A discriminated union on `kind`, identical to `@zvndev/powdb-client`'s
 * `QueryResult`, so the same code narrows whether it is talking to an embedded
 * database or a server. `kind` is one of exactly four values, and each carries
 * only its own fields:
 *
 * ```ts
 * const r = db.query("User")
 * if (r.kind === "rows") {
 *   // r.rows is string[][] here, not string[][] | undefined
 *   for (const row of r.rows) console.log(row.join(", "))
 * }
 * ```
 *
 * The runtime object is the flat `QueryResultShape` below (every field present,
 * the irrelevant ones `undefined`). This union describes which of them are
 * actually populated for a given `kind`, which the flat shape cannot express:
 * against that shape every field was optional, so reading `r.rows` needed a
 * non-null assertion even after checking `r.kind`.
 */
export type QueryResultJs =
  | { kind: "rows"; columns: string[]; rows: string[][] }
  | { kind: "scalar"; value: string }
  | { kind: "ok"; affected: bigint }
  | { kind: "message"; message: string }

/**
 * The result of a native (typed) query. Same `kind` discriminants as the
 * string-typed `QueryResultJs`; only the cell transport differs (`WireValue`
 * instead of `string`).
 */
export type NativeQueryResult =
  | { kind: "rows"; columns: string[]; rows: WireValue[][] }
  | { kind: "scalar"; value: WireValue }
  | { kind: "ok"; affected: bigint }
  | { kind: "message"; message: string }

/**
 * A positional query parameter. The parameter protocol carries only these five
 * scalar shapes: `number` (integral binds as int, otherwise float), `bigint`
 * (int), `string`, `boolean`, and `null` (PowQL `null`).
 */
export type NativeParam = number | bigint | string | boolean | null

/**
 * The stable, machine-readable code on every error raised by this addon's own
 * logic, so a caller can branch without matching on message text.
 *
 * This union does NOT cover errors raised by generated argument-coercion code,
 * which runs before any addon logic and reports napi's own status strings
 * (`"StringExpected"` and siblings). See {@link PowDBError}.
 *
 * The vocabulary mirrors the `PowDBErrorCode` union in the networked
 * `@zvndev/powdb-client` (`clients/ts/src/errors.ts`): same lowercase
 * snake_case naming, and the codes for conditions both clients have
 * (`query_failed`, `closed`) are the identical strings, so the same `switch`
 * reads correctly against an embedded database or a server. The remaining
 * codes describe embedded-only conditions the networked client cannot hit.
 *
 * `poisoned` and `open_panicked` are the two that matter operationally: both
 * mean the handle (or the data directory) is no longer usable, so an embedded
 * host should recycle or restore rather than retry.
 */
export type PowDBErrorCode =
  /**
   * Planning or execution failed: unknown table or column, type mismatch, an
   * unsupported statement. Wire error class 2.
   */
  | "query_failed"
  /** The statement failed to lex or parse. Wire error class 1. */
  | "parse_error"
  /** A time budget elapsed. Wire error class 3. */
  | "timeout"
  /** A memory or size limit was exceeded. Wire error class 4. */
  | "size_exceeded"
  /**
   * The database is open read-only and the statement requires a writer. Wire
   * error class 5.
   */
  | "readonly_refused"
  /** A constraint (a unique index) rejected the write. Wire error class 8. */
  | "constraint_violation"
  /** Execution was cancelled cooperatively. Wire error class 9. */
  | "cancelled"
  /**
   * No prebuilt native binary exists for this platform. Raised by the loader
   * before the addon is reached, so no database call has run.
   */
  | "unsupported_platform"
  /** `close()` has already been called on this handle. */
  | "closed"
  /** Opening the data directory failed (I/O, permissions, no catalog). */
  | "open_failed"
  /**
   * Opening the database panicked, so the data directory is likely corrupt.
   * Terminal: restore from a backup instead of retrying.
   */
  | "open_panicked"
  /**
   * A previous call panicked and poisoned this handle. Terminal for the
   * handle: every later call fails until the database is reopened.
   * `db.isPoisoned()` reports the same state without throwing.
   */
  | "poisoned"
  /**
   * An argument was rejected: an unknown sync mode, a parameter of a type
   * PowQL cannot bind, a malformed `databaseId`.
   */
  | "invalid_argument"
  /** Applying a retained-unit chunk to this embedded replica failed. */
  | "sync_failed"
  /** The data directory is already open elsewhere in this process. */
  | "already_open"
  /**
   * The JS engine refused an operation while a result was being built, or a
   * stored value could not be decoded. Not caller-actionable.
   */
  | "internal"

/**
 * The shape of an error raised by this addon's own logic: a plain `Error`
 * carrying a {@link PowDBErrorCode}. Narrow to it in a `catch` block to branch
 * on `code`:
 *
 * ```ts
 * try {
 *   db.query("User")
 * } catch (e) {
 *   const err = e as PowDBError
 *   if (err.code === "poisoned" || err.code === "open_panicked") throw err
 *   if (err.code === "query_failed") console.warn(err.message)
 * }
 * ```
 *
 * `code` is deliberately widened past {@link PowDBErrorCode}: an unrecognized
 * code is possible and should be rethrown rather than handled by an exhaustive
 * `switch`. Argument coercion in generated binding code raises napi's own
 * status strings (`"StringExpected"`, `"InvalidArg"`, and siblings); the
 * package entry point rewrites those to `"invalid_argument"`, since they mean
 * exactly what that code means.
 *
 * `errorClass` is the engine's own classification, numbered exactly as the
 * server numbers it on the wire (docs/errors.md), so the same branch works
 * against an embedded database and a server. It is absent only on an error
 * whose code the loader does not recognize.
 *
 * Both hold on every entry point, static factories included: an error from
 * `Database.open` carries the same rewritten `code` and the same `errorClass`
 * as one from `db.query`.
 *
 * The addon throws native `Error` instances, not instances of the networked
 * client's `PowDBError` class, so `instanceof` does not cross the two
 * packages. `code` is the portable branch.
 */
export interface PowDBError extends Error {
  code: PowDBErrorCode | (string & {})
  errorClass?: number
}
